	SELECT NVL(MAX(surv_no), 0) + 1 FROM survey	

INSERT INTO survey
		(
			surv_no
			, class_id
			, notice_no
			, surv_title
			, start_date
			, end_date

				, surv_status

			, account_type
		)
		VALUES
		(
			#{survNo}
			, #{classId}


					, #{noticeNo}


					, 1


			, #{survTitle}
			, #{startDate}
			, #{endDate}

				, #{survStatus}

			, #{accountType}
		)
